-- ============================================================
-- Offerr鹅 - 9 份示范简历 Seed（K8-5-44-B：按新字段契约重写）
-- 目标表：resumes（K8-5-51-B 替代 resume_versions）
-- 新契约：project(5字段) / internship(5字段) / cert(2字段) / award(2字段)
--          skills(2字段) / portfolio(works+homepage) / extra(additional_info)
-- ============================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DELETE FROM `resumes` WHERE `user_id` = 2;

INSERT INTO `resumes` (
  `id`, `user_id`, `schema_version`, `name`,
  `profile_json`, `education_json`, `project_json`, `skills_json`,
  `internship_json`, `certificates_json`, `awards_json`,
  `portfolio_json`, `extra_json`
) VALUES

