  '[{"school":"清华大学","degree":"硕士","major":"计算机科学与技术","department":"计算机科学与技术系","start_date":"2023-09","end_date":"2026-06","gpa":"3.78","gpa_scale":"4.0","rank":"前 15%","core_courses":"机器学习、深度学习、自然语言处理、信息检索、大规模数据挖掘、高级算法设计","research_direction":"推荐系统、用户行为建模、表示学习","lab":"智能信息处理与推荐系统实验室","paper_summary":"参与推荐系统方向论文实验与消融分析，主要负责用户行为序列建模、负采样策略对比、离线指标复现实验和误差样例分析。目前论文仍处于实验补充和投稿准备阶段。"},{"school":"北京邮电大学","degree":"本科","major":"软件工程","department":"计算机学院","start_date":"2019-09","end_date":"2023-06","gpa":"3.62","gpa_scale":"4.0","rank":"前 20%","core_courses":"数据结构、操作系统、数据库系统、计算机网络、概率论与数理统计、软件工程、Java 程序设计、数据库课程设计","research_direction":"","lab":"","paper_summary":""}]',

  '[{"name":"多目标推荐排序模型实验平台","role":"核心开发者","start_date":"2024-03","end_date":"2024-11","description":"面向实验室推荐系统研究场景，搭建用于多目标排序模型实验、指标对比和实验记录管理的平台。平台支持召回结果导入、特征拼接、模型训练、离线评估和实验复现。我主要负责样本构建、特征处理、模型训练脚本和离线评估模块开发，使用 Python、PyTorch 实现排序模型训练流程，基于 Faiss 完成向量检索实验，使用 Redis 缓存实验结果，并通过 MySQL 管理实验配置和指标数据。项目中实现了 NDCG、Recall、AUC 等离线评估指标计算，并用 Docker 统一实验环境。最终将单次实验配置准备时间从约 40 分钟降低到 10 分钟以内，支持 5 类排序模型在同一数据集上的离线指标对比，累计完成 20 余组消融实验记录，为后续论文实验提供了数据支持。"},{"name":"基于用户行为序列的点击率预估模型复现","role":"算法实现与实验分析","start_date":"2023-10","end_date":"2024-01","description":"基于公开电商行为数据集，复现用户兴趣建模相关方法，对比传统 Wide&Deep 模型与序列兴趣建模方法在点击率预估任务中的表现差异。我使用 Python、PyTorch 实现 Embedding、Attention Pooling 和序列兴趣建模模块，使用 Pandas、NumPy 完成数据清洗、用户行为序列截断和负样本构造，并通过 Scikit-learn 搭建基础对比模型。实验过程中重点分析不同序列长度、负采样比例对模型效果的影响，整理训练日志、指标变化和错误样本分析。最终在验证集上相比基础 LR 模型 AUC 提升约 6.8%，整理形成 12 页实验报告，并沉淀出一套可复用的 CTR 任务训练模板。"},{"name":"论文阅读与实验复现管理工具","role":"个人开发者","start_date":"2024-12","end_date":"2025-02","description":"为解决论文阅读、实验配置和复现实验记录分散的问题，开发了一个轻量级工具，用于管理论文笔记、实验配置、指标结果和复盘结论。项目使用 Python、FastAPI 构建后端 API，SQLite 存储论文和实验记录，Vue 实现前端界面，并支持 Markdown 导出。我独立设计了论文、实验、指标、结论四类核心数据结构，实现实验记录增删改查、按论文方向和模型类型筛选等能力。项目累计整理 30 余篇推荐系统和表示学习相关论文笔记，管理 40 余条实验配置和指标结果，帮助自己将论文阅读和实验复盘从零散记录转为结构化沉淀。"}]',

  '{"professional_skills":"Python、C++、SQL、Shell、Go、PyTorch、Scikit-learn、Pandas、NumPy、Faiss、Redis、MySQL、Docker、Linux、Git、Hive、Spark 基础、推荐系统离线评估、实验复现、数据分析","ai_application":"熟悉使用大模型辅助论文阅读、实验代码理解、错误日志定位和实验报告整理。能够通过结构化提示词将论文方法拆解为数据处理、模型结构、训练目标、评估指标和实验结论五部分，并用于加速算法复现和实验复盘。使用 AI 工具时会主动核对论文原文、代码实现和实验结果，避免直接采信生成内容。"}',

  '[{"company":"某头部内容平台","position":"搜索推荐算法实习生","start_date":"2024-07","end_date":"2024-10","description":"参与内容推荐场景的召回与排序实验，围绕用户短期兴趣变化、内容冷启动和负反馈样本处理进行实验分析。实习期间使用 Python、PyTorch 进行模型实验，使用 Spark、Hive 处理大规模用户行为数据，并通过 SQL 完成数据分析和样本质量核验。主要工作包括用户行为特征统计、异常曝光样本定位、召回侧特征实验对比和小流量实验前的数据核验。期间参与 8 组离线实验，输出 4 份实验分析文档，其中 2 项特征策略进入小流量验证，同时针对冷启动内容样本进行了分层分析，形成低曝光内容的特征分布报告。"}]',

  '{"language_exams":[{"type":"CET-6","score":"568"}],"certificates":[{"name":"中国计算机学会 CSP 认证","description":"专业能力认证，CSP-S 级别，成绩排名前 20%，2023 年 3 月获得。"},{"name":"阿里云机器学习平台 PAI 基础课程认证","description":"云计算与机器学习平台相关课程认证，2024 年 5 月通过。"}]}',

  '[{"name":"研究生学业一等奖学金","description":"校级奖学金，2024 年 10 月获得，基于课程成绩、科研参与和综合表现评定。"},{"name":"全国大学生数学建模竞赛省级二等奖","description":"省级二等奖，2021 年 11 月获得，主要负责数据建模、算法实现和结果可视化部分。"}]',

  '{"works":[{"name":"CTR 序列建模复现实验项目","url":"https://github.com/demo-user/ctr-sequence-model","password":""},{"name":"推荐排序实验记录模板","url":"https://github.com/demo-user/recsys-exp-template","password":""},{"name":"论文阅读与实验复现管理工具","url":"https://github.com/demo-user/paper-exp-tracker","password":""}],"homepage":"https://github.com/demo-user"}',

  '{"additional_info":"我对推荐系统和机器学习方向有持续兴趣，习惯通过实验数据验证想法，也愿意做长期、细致的实验复盘。相比只关注模型结构，我更关注数据质量、样本构造、评价指标和线上业务目标之间的关系。过去的科研和实习经历让我逐渐理解，算法岗位不仅需要建模能力，也需要把业务目标、数据分布和工程实现结合起来。希望在算法工程实习中进一步提升对真实业务场景的理解，把科研训练中的分析能力落到实际产品问题中。目前更希望参与推荐系统、搜索算法、机器学习平台或用户行为建模相关实习，可以接受需要长期实验、反复调参和细致复盘的工作节奏，也愿意继续补齐工程化和线上实验经验。"}'
