(202, 2, 2, '02-211后台开发-岗位匹配', '{"name":"陈嘉佑","phone":"13900010002","email":"chenjiayou.backend@example.com","city":"南京"}', '[{"school":"南京邮电大学","degree":"本科","major":"软件工程","department":"计算机学院","start_date":"2022-09","end_date":"2026-06","gpa":"3.41","gpa_scale":"4.0","rank":"前 35%","core_courses":"数据结构、操作系统、计算机网络、数据库系统、Java 程序设计、软件工程、Web 应用开发、Linux 基础","research_direction":"","lab":"","paper_summary":""}]', '[{"name":"校园二手交易平台","role":"后端主要开发者","start_date":"2024-03","end_date":"2024-06","description":"面向校园内二手书籍、电子产品和生活用品交易场景，开发了一个前后端分离的校园二手交易平台。我主要负责后端接口设计、数据库表结构设计、商品发布、商品搜索、订单创建、收藏、评论和用户登录等模块。项目使用 Spring Boot 构建后端服务，MySQL 存储用户、商品和订单数据，Redis 用于缓存热门商品和短信验证码，JWT 完成登录态校验。开发过程中重点处理了商品状态流转、订单重复提交、接口参数校验和基础权限判断等问题。通过该项目，我对常见后台业务的 Controller、Service、Mapper 分层、数据库事务和接口联调流程有了比较完整的实践。"},{"name":"在线课程学习与进度管理系统","role":"后端开发成员","start_date":"2024-09","end_date":"2024-12","description":"项目面向校内课程学习场景，支持课程列表、章节内容、学习进度记录和后台课程管理。我负责课程、章节、学习记录相关接口开发，并参与部分数据库设计和前后端联调。系统使用 Spring Boot、MyBatis Plus、MySQL 和 Redis 实现，课程基础信息存储在 MySQL 中，学习进度通过接口上报并进行更新。开发中重点处理了学习进度重复上报、课程章节关联查询、分页列表查询和基础异常返回。项目让我更熟悉后端接口从需求拆解、字段设计、SQL 编写到接口测试的完整流程，也意识到数据一致性和接口边界设计在业务系统中的重要性。"},{"name":"个人博客与后台管理系统","role":"个人开发者","start_date":"2023-10","end_date":"2024-01","description":"为了练习后端基础能力，独立完成了一个个人博客与后台管理系统，支持文章发布、分类管理、标签管理、评论管理和后台登录。后端使用 Java、Spring Boot 和 MySQL 实现，前端使用 Vue 完成基础页面，接口通过 JWT 做登录认证。项目中实现了文章分页查询、条件筛选、评论审核和后台管理等功能，并使用 Nginx 和云服务器完成简单部署。虽然项目规模不大，但帮助我系统练习了 RESTful API 设计、数据库表关联、基础权限校验、日志排查和线上部署流程。"}]', '{"professional_skills":"Java、Go 基础、Spring Boot、MyBatis Plus、MySQL、Redis、Linux、Docker 基础、Nginx 基础、Git、Maven、RESTful API、JWT、数据库事务、索引基础、接口联调、Postman、基础 SQL 优化","ai_application":"会使用 CodeBuddy、ChatGPT 等 AI 工具辅助需求拆解、接口设计、SQL 排查、Bug 定位和文档整理。使用 AI 生成代码后会结合项目上下文进行检查，重点核对字段名、接口路径、异常处理和数据库操作，避免直接复制无法运行的代码。"}', '[{"company":"南京某软件技术有限公司","position":"Java 后端开发实习生","start_date":"2025-01","end_date":"2025-04","description":"参与公司内部业务管理系统的后端接口开发，主要负责基础数据管理、列表查询、详情查询和部分配置项维护接口。实习期间使用 Spring Boot、MyBatis Plus 和 MySQL 完成业务接口开发，使用 Redis 做部分字典数据和热点配置缓存，并通过 Postman 与前端进行接口联调。参与修复过分页参数异常、空指针、SQL 查询条件遗漏和接口返回字段不一致等问题，也根据测试反馈补充了部分参数校验和统一错误提示。通过这段实习，我对企业项目中的分层结构、接口规范、代码评审和测试联调流程有了更直接的认识。"}]', '{"language_exams":[{"type":"CET-4","score":"512"}],"certificates":[{"name":"软件设计师","description":"计算机技术与软件专业技术资格考试中级证书，主要覆盖软件工程、数据库、操作系统、计算机网络和程序设计基础。"},{"name":"阿里云云计算基础课程认证","description":"完成云服务器、数据库、网络与基础运维相关课程学习，对云上部署和基础资源管理有初步了解。"}]}', '[{"name":"校级程序设计竞赛二等奖","description":"校级程序设计竞赛二等奖，主要考察数据结构、基础算法和编程实现能力。"},{"name":"软件工程课程设计优秀项目","description":"课程设计项目获得优秀评价，负责后端接口和数据库设计部分。"}]', '{"works":[{"name":"校园二手交易平台","url":"https://github.com/demo-user/campus-trade-backend","password":""},{"name":"在线课程学习与进度管理系统","url":"https://github.com/demo-user/course-progress-system","password":""},{"name":"个人博客与后台管理系统","url":"https://github.com/demo-user/blog-admin-system","password":""}],"homepage":"https://github.com/demo-user"}', '{"additional_info":"我以后台开发实习为主要求职方向，熟悉 Java 后端开发的基础流程，做过课程管理、二手交易、博客后台等项目，也有一段中小型企业后端实习经历。相比算法或产品方向，我更适合从业务接口、数据库设计、缓存使用和系统联调等基础后端工作做起。目前对 Spring Boot、MySQL、Redis 和接口工程化比较熟悉，但在高并发、分布式系统和复杂业务建模方面仍需要继续提升。希望进入真实业务团队，在代码规范、问题排查、系统设计和线上稳定性方面持续积累。"}' ),

-- ===== 03-二本产品经理-岗位匹配 =====
(203, 2, 2, '03-二本产品经理-岗位匹配', '{"name":"周雨桐","phone":"13900010003","email":"zhouyutong.pm@example.com","city":"广州"}', '[{"school":"合肥师范学院","degree":"本科","major":"信息管理与信息系统","department":"经济与管理学院","start_date":"2022-09","end_date":"2026-06","gpa":"3.48","gpa_scale":"4.0","rank":"前 25%","core_courses":"管理信息系统、数据库原理、统计学、市场营销、项目管理、用户研究、Python 数据分析、电子商务概论","research_direction":"","lab":"","paper_summary":""}]', '[{"name":"校园活动报名与志愿服务小程序","role":"产品负责人","start_date":"2024-03","end_date":"2024-06","description":"面向校内社团活动报名、志愿服务报名和活动签到场景，设计了一套轻量级小程序原型。我负责需求调研、流程设计、原型绘制和需求文档整理，前期访谈了 18 名学生和 3 名社团负责人，梳理出活动信息分散、报名统计困难、签到核验效率低等问题。项目中使用 Axure 绘制活动列表、报名表单、报名记录、签到二维码和后台统计页面，整理了功能清单、页面流程图和字段说明，并与 2 名开发同学进行接口字段讨论。最终形成 20 余页 PRD 和可交互原型，帮助课程团队完成 Demo 展示，也让我理解了产品方案从问题发现到流程落地的完整过程。"},{"name":"新生选课体验优化调研","role":"产品分析与用户调研","start_date":"2024-09","end_date":"2024-11","description":"围绕新生选课流程复杂、课程信息不清晰和退补选规则理解困难等问题，完成了一次选课体验优化调研。我通过问卷收集 126 份有效反馈，并访谈 12 名不同专业学生，整理出课程筛选、时间冲突、教师评价、学分要求和退补选提醒五类核心痛点。基于调研结果，我使用 Excel 做反馈分类统计，使用 XMind 梳理用户路径，并输出选课流程优化建议，包括课程信息卡片化、冲突提醒前置、培养方案对照和常见问题说明等。该项目提升了我对用户调研、数据归纳和产品改进建议表达的理解。"},{"name":"校园闲置交易平台产品原型","role":"产品设计者","start_date":"2023-11","end_date":"2024-01","description":"针对学生闲置物品流转效率低、微信群信息容易沉底和交易信任不足的问题，设计校园闲置交易平台原型。项目包含商品发布、分类浏览、关键词搜索、收藏、私信沟通、交易状态和举报反馈等核心流程。我负责竞品分析、用户路径设计、页面原型和需求说明，参考闲鱼、转转以及校内二手群的使用习惯，重点优化商品发布流程和交易安全提示。最终输出一套包含 30 余个页面的低保真原型和功能说明文档，并在班级内收集试用反馈，对发布表单、筛选条件和商品详情页进行了两轮迭代。"}]', '{"professional_skills":"Axure、Figma、墨刀、XMind、Visio、Excel、PPT、SQL 基础、Python 数据分析基础、问卷设计、用户访谈、竞品分析、用户画像、流程图、PRD 文档、低保真原型、数据整理、活动运营基础","ai_application":"会使用 ChatGPT、腾讯元宝等 AI 工具辅助竞品信息整理、用户访谈提纲设计、PRD 结构梳理、原型文案优化和数据分析思路拆解。使用 AI 结果时会结合真实用户反馈和业务目标进行二次判断，不直接把生成内容当作最终结论。"}', '[{"company":"广州某互联网教育公司","position":"产品运营实习生","start_date":"2025-01","end_date":"2025-04","description":"参与在线课程产品的用户反馈收集、课程活动配置和基础产品需求整理工作。实习期间主要负责整理用户咨询和反馈问题，将课程学习进度异常、优惠券使用疑问、课程页面信息不清晰等问题分类记录，并协助产品经理输出小需求说明。我参与过课程详情页文案调整、活动页配置检查和后台数据核对，使用 Excel 整理活动报名、课程点击和用户反馈数据，定期输出问题汇总表。通过这段实习，我对产品经理和运营、研发、设计之间的协作方式有了更真实的认识，也意识到产品工作不仅是画原型，更重要的是理解用户问题、明确优先级并推动方案落地。"}]', '{"language_exams":[{"type":"CET-4","score":"489"}],"certificates":[{"name":"全国计算机等级考试二级 MS Office 高级应用","description":"掌握常用办公软件、表格处理和基础数据整理能力。"},{"name":"Axure RP 产品原型设计课程证书","description":"完成产品原型设计课程学习，能够独立绘制页面原型、交互说明和基础流程图。"}]}', '[{"name":"校级互联网+创新创业大赛三等奖","description":"参与校园服务类项目方案设计，主要负责用户调研、产品原型和路演材料整理。"},{"name":"优秀学生干部","description":"在学院学生组织中负责活动策划、报名统计和跨部门沟通，具备一定组织协调经验。"}]', '{"works":[{"name":"校园活动报名与志愿服务小程序原型","url":"https://demo.example.com/campus-activity-prototype","password":""},{"name":"新生选课体验优化调研报告","url":"https://demo.example.com/course-selection-research","password":""},{"name":"校园闲置交易平台产品原型","url":"https://demo.example.com/campus-trade-prototype","password":""}],"homepage":"https://demo.example.com/zhouyutong"}', '{"additional_info":"我希望从产品经理或产品运营相关实习开始积累真实业务经验。虽然学校背景和技术深度不算突出，但我对用户需求、产品流程和信息结构比较敏感，愿意从调研、文档、原型、数据整理和跨角色沟通这些基础工作做起。过去的课程项目和实习经历让我认识到，产品岗位不是单纯提出想法，而是要把用户问题、业务目标、研发成本和上线节奏放在一起判断。当前希望进入互联网产品团队，继续提升需求拆解、数据分析、原型表达和项目推进能力。"}' ),

-- ===== 04-职业探索型学生-岗位推荐 =====
(204, 2, 2, '04-职业探索型学生-岗位推荐', '{"name":"许知夏","phone":"13900010004","email":"xuzhixia.explore@example.com","city":"成都"}', '[{"school":"四川师范大学","degree":"本科","major":"数字媒体技术","department":"计算机科学学院","start_date":"2022-09","end_date":"2026-06","gpa":"3.36","gpa_scale":"4.0","rank":"前 40%","core_courses":"数字媒体技术导论、网页设计、数据库基础、Python 程序设计、用户体验设计、传播学概论、数据可视化、交互设计基础","research_direction":"","lab":"","paper_summary":""}]', '[{"name":"校园生活服务信息聚合平台","role":"产品与内容协作者","start_date":"2024-03","end_date":"2024-06","description":"围绕校园内活动信息、社团招新、二手信息和学习资源分散的问题，参与设计一个校园生活服务信息聚合平台。项目中我主要负责用户调研、内容分类、页面信息结构和基础原型整理，访谈了多名同学了解他们获取校园信息的习惯，并将信息归纳为活动、资源、闲置、问答四类。项目使用低保真原型呈现首页信息流、分类筛选、详情页和发布入口，并结合课程要求整理了需求说明和展示材料。这个项目让我发现自己既对产品体验感兴趣，也喜欢做信息整理和用户沟通，但还没有完全确定未来应该走产品、运营还是内容方向。"},{"name":"城市周末出行内容账号运营实践","role":"内容策划与数据整理","start_date":"2024-07","end_date":"2024-10","description":"出于个人兴趣，和同学一起尝试运营一个城市周末出行内容账号，主要记录展览、市集、书店、咖啡店和短途路线。我负责选题整理、图文结构、发布时间记录和基础数据复盘，使用表格记录不同主题内容的浏览量、收藏量和互动情况，并根据反馈调整标题、封面和内容结构。过程中累计整理 40 余个本地生活选题，发布多篇图文内容。虽然账号规模不大，但这段经历让我对内容运营、用户兴趣判断和数据反馈有了初步认识，也让我意识到自己比较喜欢和生活方式、用户体验相关的工作。"},{"name":"课程作品：个人成长记录与习惯追踪小工具","role":"个人开发与设计","start_date":"2023-11","end_date":"2024-01","description":"为了练习网页设计和简单数据记录能力，独立完成了一个个人成长记录与习惯追踪小工具。项目支持记录阅读、运动、学习、睡眠等日常行为，并用简单图表展示一段时间内的变化。我使用 HTML、CSS、JavaScript 和本地存储实现基础功能，重点练习页面布局、表单交互和数据可视化呈现。虽然技术难度不高，但这个项目帮助我把生活兴趣和数字工具结合起来，也让我对用户使用习惯、信息可视化和轻量产品设计产生了兴趣。"}]', '{"professional_skills":"Python 基础、HTML、CSS、JavaScript 基础、SQL 基础、Excel、PPT、Figma、Axure 基础、Canva、剪映、数据整理、问卷设计、用户访谈、内容策划、图文编辑、活动策划、信息分类、基础数据分析","ai_application":"会使用 ChatGPT、腾讯元宝等 AI 工具辅助选题发散、问卷提纲设计、内容结构整理、PPT 大纲生成和学习资料归纳。使用 AI 工具时会结合真实反馈进行二次筛选，主要把它作为提高整理效率和扩展思路的辅助工具。"}', '[{"company":"成都某文化活动策划工作室","position":"新媒体运营实习生","start_date":"2025-01","end_date":"2025-03","description":"参与线下文化活动和展览项目的新媒体内容整理、活动信息发布和基础用户反馈收集。实习期间主要负责活动图文素材整理、推文初稿撰写、报名信息统计和评论区问题归类，也协助完成过活动现场签到和用户问卷回收。通过这段实习，我接触到内容发布、活动执行、用户沟通和数据整理等工作，发现自己对内容运营、用户体验和活动策划都有兴趣，但也意识到自己还需要进一步明确职业方向，提升数据分析和项目推进能力。"}]', '{"language_exams":[{"type":"CET-4","score":"476"}],"certificates":[{"name":"全国计算机等级考试二级 MS Office 高级应用","description":"掌握常用办公软件、表格处理和基础数据整理能力。"},{"name":"普通话水平测试二级甲等","description":"具备较好的普通话表达能力，适合参与讲解、主持、活动执行和用户沟通类工作。"}]}', '[{"name":"校级优秀志愿者","description":"参与多次校内大型活动和社区志愿服务，主要负责签到引导、物资整理和现场沟通。"},{"name":"学院新媒体中心优秀干事","description":"在学院新媒体中心参与图文编辑、活动报道和选题整理，表现稳定，协作意识较好。"}]', '{"works":[{"name":"城市周末出行内容账号作品集","url":"https://demo.example.com/weekend-city-life","password":""},{"name":"校园生活服务平台课程原型","url":"https://demo.example.com/campus-life-prototype","password":""},{"name":"个人习惯追踪小工具 Demo","url":"https://demo.example.com/habit-tracker-demo","password":""}],"homepage":"https://demo.example.com/xuzhixia"}', '{"additional_info":"我目前还在探索更适合自己的职业方向。大学期间接触过网页设计、内容运营、用户调研、活动策划和基础数据整理，也参与过一些生活方式内容和校园服务类项目。相比单一技术深耕，我更容易被用户体验、内容表达、信息整理和真实生活场景吸引。现阶段希望通过岗位推荐了解产品运营、内容运营、用户研究、活动策划、产品助理等方向的差异，再结合自己的项目经历和性格特点逐步收敛目标。我愿意从基础执行、数据整理、用户反馈和跨角色沟通做起，在真实业务环境中判断自己更适合的长期方向。"}' ),

-- ===== 05-优秀但不适合互联网-岗位推荐 =====
(205, 2, 2, '05-优秀但不适合互联网-岗位推荐', '{"name":"沈亦然","phone":"13900010005","email":"shenyiran.steady@example.com","city":"武汉"}', '[{"school":"华中师范大学","degree":"本科","major":"教育技术学","department":"教育信息技术学院","start_date":"2022-09","end_date":"2026-06","gpa":"3.82","gpa_scale":"4.0","rank":"前 8%","core_courses":"教育技术学导论、学习科学、教育心理学、教学系统设计、教育数据分析、Python 程序设计、数据库基础、统计学、数字化课程设计","research_direction":"","lab":"","paper_summary":""}]', '[{"name":"高校课程学习行为分析报告","role":"数据整理与报告撰写负责人","start_date":"2024-03","end_date":"2024-06","description":"围绕学生在线课程学习过程中的登录频次、学习时长、作业提交和课程完成情况，完成了一份课程学习行为分析报告。我主要负责数据清洗、指标设计、可视化图表整理和报告撰写，使用 Excel、Python 和基础统计方法分析不同年级、不同课程类型学生的学习行为差异。项目中将原始学习记录整理为学习活跃度、任务完成率、阶段性波动和课程参与度等指标，并根据数据结果提出课程提醒、学习节奏设计和助教跟进建议。最终形成 30 余页分析报告，被课程组用于复盘线上教学效果。这个项目让我认识到自己更适合长期、细致、结构化的数据分析和报告型工作。"},{"name":"数字化课程资源建设项目","role":"课程资源整理与质量检查负责人","start_date":"2024-09","end_date":"2024-12","description":"参与学院数字化课程资源建设项目，主要整理课程视频、课件、作业说明、知识点标签和学习任务说明。我负责制定课程资源命名规范、目录结构和检查清单，并协助老师将原本分散的课程材料整理为可复用的线上学习资源。项目过程中，我使用 Excel 跟踪资源完成情况，使用 Markdown 整理知识点说明，并对课程内容的完整性、格式一致性和学生理解难度进行检查。最终完成 6 门课程的资源梳理和质量核对。这段经历体现出我在耐心、规范意识和长期整理类任务上的优势。"},{"name":"学生发展支持服务调研","role":"问卷设计与访谈整理负责人","start_date":"2023-11","end_date":"2024-01","description":"围绕学生学习压力、时间管理、职业规划和校园支持服务需求，参与完成学生发展支持服务调研。我负责问卷题项设计、访谈提纲整理、数据录入和访谈纪要归纳，累计回收 200 余份问卷，并整理 15 名学生的访谈内容。项目中将反馈归纳为学习适应、情绪压力、升学就业、信息获取和师生沟通五类问题，并提出面向辅导员和学院管理的改进建议。相比追求快速业务增长的项目，我更喜欢这类能够沉下心分析真实问题、输出稳定改进建议的工作。"}]', '{"professional_skills":"Excel、PPT、Word、Python 基础、SQL 基础、SPSS 基础、问卷设计、访谈整理、数据清洗、数据可视化、报告撰写、课程资源整理、教学设计、用户反馈归纳、项目进度跟踪、文档规范化、跨部门沟通","ai_application":"会使用 ChatGPT、腾讯元宝等 AI 工具辅助文献摘要、访谈纪要归纳、报告大纲生成、问卷题项优化和课程资料整理。使用 AI 工具时会人工核对原始材料和数据来源，更倾向于将 AI 作为提高整理效率和结构化表达的辅助工具，而不是直接替代判断。"}', '[{"company":"武汉某教育科技研究机构","position":"教学研究助理实习生","start_date":"2025-01","end_date":"2025-04","description":"参与数字化课程评估和教学支持相关工作，主要负责课程资料整理、问卷数据录入、访谈纪要归档和阶段性报告初稿撰写。实习期间协助研究员整理多门课程的学习反馈数据，使用 Excel 进行基础统计和图表制作，并将教师访谈和学生反馈归纳为课程内容、学习节奏、作业难度和平台体验等类别。工作节奏相对稳定，但需要耐心、细致和较强的文档规范意识。我在这段实习中表现出较好的执行力和责任心，也更加确认自己适合教育研究、数据分析、项目支持或公共服务类岗位。"}]', '{"language_exams":[{"type":"CET-6","score":"542"},{"type":"普通话水平测试","score":"二级甲等"}],"certificates":[{"name":"全国计算机等级考试二级 Python","description":"掌握 Python 基础语法、数据处理和简单程序设计能力。"},{"name":"教师资格证笔试合格证明","description":"已通过中学信息技术教师资格证笔试，对教育学、心理学和学科教学基础有一定了解。"}]}', '[{"name":"国家励志奖学金","description":"国家级奖学金，基于学习成绩、综合表现和家庭经济情况评定。"},{"name":"校级优秀学生干部","description":"在学院学生组织中长期负责资料整理、活动协调和通知发布，工作稳定、认真、责任心强。"},{"name":"学院学业一等奖学金","description":"学院奖学金，连续两学年获得，成绩排名保持在专业前列。"}]', '{"works":[{"name":"高校课程学习行为分析报告","url":"https://demo.example.com/course-learning-analysis","password":""},{"name":"数字化课程资源整理规范模板","url":"https://demo.example.com/course-resource-standard","password":""},{"name":"学生发展支持服务调研报告","url":"https://demo.example.com/student-support-research","password":""}],"homepage":"https://demo.example.com/shenyiran"}', '{"additional_info":"我的学习成绩和执行力比较稳定，做事认真、耐心，适合需要长期投入、规范整理、数据分析和报告输出的工作场景。相比高强度、强竞争、快速迭代的互联网业务环境，我更适合教育科技、公共服务、数据分析、教学研究、项目支持、用户研究助理或职能管理类岗位。过去的课程项目和实习经历让我发现，自己更擅长把复杂信息整理清楚、从数据和访谈中归纳问题，并形成可执行的改进建议。希望未来选择一个节奏相对稳定、能够持续积累专业能力和社会价值感的方向，而不是单纯追求高压增长和短期结果。"}' ),

-- ===== 06-211后台开发-版本对比A =====
(206, 2, 2, '06-211后台开发-版本对比A', '{"name":"刘明轩","phone":"13900010006","email":"liumingxuan.backend@example.com","city":"苏州"}', '[{"school":"苏州大学","degree":"本科","major":"软件工程","department":"计算机科学与技术学院","start_date":"2022-09","end_date":"2026-06","gpa":"3.39","gpa_scale":"4.0","rank":"前 35%","core_courses":"数据结构、操作系统、计算机网络、数据库系统、Java 程序设计、软件工程、Web 开发基础、Linux 基础","research_direction":"","lab":"","paper_summary":""}]', '[{"name":"图书借阅管理系统","role":"后端开发成员","start_date":"2023-10","end_date":"2024-01","description":"参与开发一个面向班级课程设计的图书借阅管理系统，主要功能包括用户登录、图书查询、图书借阅、归还记录和后台图书管理。我主要负责部分后端接口开发和数据库表设计，使用 Java、Spring Boot、MySQL 完成基础业务功能，并配合前端完成接口联调。项目中实现了图书列表查询、借阅记录新增、归还状态更新和简单的管理员管理功能。通过这个项目，我熟悉了 Spring Boot 项目的基本目录结构、Controller、Service、Mapper 分层和 MySQL 的基础使用。"},{"name":"校园报修管理系统","role":"后端开发成员","start_date":"2024-03","end_date":"2024-06","description":"参与开发校园报修管理系统，系统支持学生提交报修单、管理员查看报修列表、修改处理状态和查询历史记录。我负责报修单相关接口和部分后台管理接口，使用 Spring Boot、MyBatis Plus、MySQL 实现基础增删改查功能。开发过程中主要完成了报修单创建、分页查询、状态更新和按条件筛选等功能，也参与了接口测试和简单 Bug 修复。该项目让我对后台管理类系统的业务流程、数据库字段设计和前后端协作有了初步理解。"},{"name":"个人博客系统","role":"个人开发者","start_date":"2024-07","end_date":"2024-09","description":"为了练习后端开发基础，独立完成了一个个人博客系统，支持文章发布、文章分类、标签管理和评论展示等功能。后端使用 Spring Boot 和 MySQL 实现，前端使用 Vue 完成简单页面。我完成了文章增删改查、分类标签管理、登录认证和评论列表查询等功能，并尝试将项目部署到云服务器。项目规模不大，但帮助我熟悉了 RESTful API、数据库表关联、JWT 登录认证和基础部署流程。"}]', '{"professional_skills":"Java、Go 基础、Spring Boot、MyBatis Plus、MySQL、Redis 基础、Linux 基础、Docker 基础、Nginx 基础、Git、Maven、RESTful API、JWT、Postman、基础 SQL 编写、接口联调","ai_application":"会使用 ChatGPT、CodeBuddy 等 AI 工具辅助理解报错信息、生成接口文档、整理学习笔记和排查基础代码问题。当前主要把 AI 工具作为学习和排错辅助，生成内容会结合项目代码进行二次检查。"}', '[{"company":"苏州某软件服务公司","position":"Java 后端开发实习生","start_date":"2025-01","end_date":"2025-03","description":"参与公司内部管理系统的部分接口开发和维护工作，主要负责基础数据查询、列表分页、详情查询和简单配置项管理。实习期间使用 Spring Boot、MyBatis Plus 和 MySQL 完成业务接口开发，也使用 Postman 与前端进行接口联调。工作中修复过字段返回不一致、查询条件遗漏、空指针异常等问题，并根据测试反馈补充了部分参数校验。通过这段实习，我对企业项目的代码结构、接口开发流程和测试反馈处理有了初步认识。"}]', '{"language_exams":[{"type":"CET-4","score":"506"}],"certificates":[{"name":"软件设计师","description":"计算机技术与软件专业技术资格考试中级证书，覆盖软件工程、数据库、操作系统和计算机网络等基础知识。"},{"name":"阿里云云计算基础课程认证","description":"完成云服务器、数据库和基础网络相关课程学习，对云上部署流程有初步了解。"}]}', '[{"name":"校级程序设计竞赛三等奖","description":"校级程序设计竞赛三等奖，主要考察基础算法和代码实现能力。"},{"name":"软件工程课程设计优秀项目","description":"课程设计项目获得优秀评价，主要负责后端接口开发和数据库表设计。"}]', '{"works":[{"name":"图书借阅管理系统","url":"https://github.com/demo-user/library-system-v1","password":""},{"name":"校园报修管理系统","url":"https://github.com/demo-user/campus-repair-system","password":""},{"name":"个人博客系统","url":"https://github.com/demo-user/blog-system-basic","password":""}],"homepage":"https://github.com/demo-user"}', '{"additional_info":"我目前以后台开发实习为主要目标，熟悉 Java 后端开发的基础流程，做过图书管理、校园报修、个人博客等课程或个人项目，也有一段基础后端实习经历。当前简历中的项目经历相对完整，但对项目价值、技术细节和个人贡献的表达还不够聚焦，很多内容停留在功能实现层面。后续希望继续补强 MySQL、Redis、接口设计、并发基础和线上问题排查能力，也希望通过简历迭代更清楚地呈现自己的后端开发能力。"}' ),

-- ===== 07-211后台开发-版本对比B =====
(207, 2, 2, '07-211后台开发-版本对比B', '{"name":"刘明轩","phone":"13900010006","email":"liumingxuan.backend@example.com","city":"苏州"}', '[{"school":"苏州大学","degree":"本科","major":"软件工程","department":"计算机科学与技术学院","start_date":"2022-09","end_date":"2026-06","gpa":"3.39","gpa_scale":"4.0","rank":"前 35%","core_courses":"数据结构、操作系统、计算机网络、数据库系统、Java 程序设计、软件工程、Web 开发基础、Linux 基础","research_direction":"","lab":"","paper_summary":""}]', '[{"name":"图书借阅管理系统","role":"后端核心开发者","start_date":"2023-10","end_date":"2024-01","description":"面向课程设计场景开发图书借阅管理系统，支持图书检索、借阅申请、归还记录、逾期状态和后台图书维护等功能。我主要负责后端接口设计、数据库表结构设计和核心借阅流程实现。项目使用 Spring Boot、MyBatis Plus 和 MySQL 完成业务开发，通过 JWT 做登录认证，并围绕借阅、归还和库存数量变化设计了基础事务控制，避免同一本图书被重复借出。相比早期版本，我进一步补充了接口参数校验、统一异常返回和借阅记录分页查询逻辑，并整理了接口文档用于前后端联调。该项目让我从简单增删改查进一步理解了状态流转、数据库事务和业务边界校验在后台系统中的作用。"},{"name":"校园报修管理系统","role":"后端主要开发者","start_date":"2024-03","end_date":"2024-06","description":"参与开发校园报修管理系统，面向学生报修、管理员分派、维修状态跟踪和历史记录查询等场景。我负责报修单、状态流转、后台筛选查询和处理记录相关接口开发，使用 Spring Boot、MyBatis Plus、MySQL 和 Redis 完成后端实现。项目中将报修单状态拆分为待处理、处理中、已完成、已取消等阶段，并在接口层补充状态流转校验，避免重复处理和非法状态变更。针对管理员高频查询报修类型和处理状态的问题，使用 Redis 缓存部分字典配置，减少重复数据库查询。开发过程中还参与了分页查询优化、接口返回字段统一和异常日志排查，使前后端联调过程更稳定。"},{"name":"个人博客与后台管理系统","role":"个人开发者","start_date":"2024-07","end_date":"2024-09","description":"独立开发个人博客与后台管理系统，支持文章发布、分类标签管理、评论审核、后台登录和文章检索等功能。后端使用 Spring Boot、MySQL 和 Redis 实现，前端使用 Vue 完成基础管理页面，并通过 Nginx 部署到云服务器。项目中围绕文章列表查询设计了分页和条件筛选，使用 JWT 实现后台登录认证，使用 Redis 缓存部分热门文章和分类信息，并补充了基础操作日志方便排查问题。相比早期仅完成基础功能的版本，我进一步整理了数据库表关系、接口文档和部署步骤，对 RESTful API 设计、缓存使用、权限校验和线上部署有了更完整的实践。"}]', '{"professional_skills":"Java、Go 基础、Spring Boot、MyBatis Plus、MySQL、Redis、Linux、Docker 基础、Nginx 基础、Git、Maven、RESTful API、JWT、数据库事务、索引基础、缓存基础、接口联调、Postman、基础 SQL 优化、异常日志排查","ai_application":"会使用 CodeBuddy、ChatGPT 等 AI 工具辅助需求拆解、接口设计、SQL 排查、Bug 定位、接口文档和项目复盘。使用 AI 生成代码后会结合项目上下文进行二次检查，重点核对字段名、接口路径、异常处理、数据库事务和缓存使用边界，避免直接复制无法运行或不符合业务逻辑的代码。"}', '[{"company":"苏州某软件服务公司","position":"Java 后端开发实习生","start_date":"2025-01","end_date":"2025-03","description":"参与公司内部业务管理系统的后端接口开发和维护工作，主要负责基础数据管理、列表查询、详情查询、配置项维护和部分接口问题修复。实习期间使用 Spring Boot、MyBatis Plus、MySQL 和 Redis 完成业务接口开发，通过 Postman 与前端进行接口联调，并根据测试反馈补充参数校验和统一错误提示。工作中修复过分页参数异常、查询条件遗漏、空指针异常、接口返回字段不一致等问题，也参与整理了部分接口说明文档。相比只完成课程项目，这段实习让我更清楚企业项目中代码规范、分层结构、测试反馈处理和上线前自查的重要性，也提升了我定位问题和沟通需求的能力。"}]', '{"language_exams":[{"type":"CET-4","score":"506"}],"certificates":[{"name":"软件设计师","description":"计算机技术与软件专业技术资格考试中级证书，覆盖软件工程、数据库、操作系统和计算机网络等基础知识。"},{"name":"阿里云云计算基础课程认证","description":"完成云服务器、数据库和基础网络相关课程学习，对云服务器部署、基础网络配置和云上资源管理有初步了解。"}]}', '[{"name":"校级程序设计竞赛三等奖","description":"校级程序设计竞赛三等奖，主要考察数据结构、基础算法和代码实现能力。"},{"name":"软件工程课程设计优秀项目","description":"课程设计项目获得优秀评价，主要负责后端接口设计、数据库表设计和核心业务流程实现。"}]', '{"works":[{"name":"图书借阅管理系统","url":"https://github.com/demo-user/library-system-v2","password":""},{"name":"校园报修管理系统","url":"https://github.com/demo-user/campus-repair-system-v2","password":""},{"name":"个人博客与后台管理系统","url":"https://github.com/demo-user/blog-admin-system-v2","password":""}],"homepage":"https://github.com/demo-user"}', '{"additional_info":"我目前以后台开发实习为主要目标，重点围绕 Java 后端、MySQL、Redis、接口设计和基础部署能力持续积累。相比早期简历中只描述功能实现，现在更能关注业务状态流转、数据库事务、接口参数校验、缓存使用和前后端联调中的边界问题。过去的课程项目和实习经历让我认识到，后端开发不仅是完成增删改查，还需要理解数据一致性、异常处理、接口规范和线上可维护性。后续希望继续补强并发编程、缓存一致性、SQL 优化和系统稳定性相关能力，在真实业务团队中提升工程质量和问题排查能力。"}' ),

-- ===== 08-211后台开发-接近投递版-简历优化 =====
(208, 2, 2, '08-211后台开发-接近投递版-简历优化', '{"name":"赵承宇","phone":"13900010008","email":"zhaochengyu.backend@example.com","city":"杭州"}', '[{"school":"杭州电子科技大学","degree":"本科","major":"软件工程","department":"计算机学院","start_date":"2022-09","end_date":"2026-06","gpa":"3.56","gpa_scale":"4.0","rank":"前 25%","core_courses":"数据结构、操作系统、计算机网络、数据库系统、Java 程序设计、软件工程、分布式系统基础、Linux 操作系统、Web 应用开发","research_direction":"","lab":"","paper_summary":""}]', '[{"name":"企业课程学习平台","role":"后端核心开发者","start_date":"2024-09","end_date":"2025-01","description":"面向企业内部培训和课程学习场景，参与开发课程学习平台，支持课程内容管理、学员权限开通、视频学习、文档学习、学习进度追踪和后台管理等功能。我主要负责后端接口设计、课程权限判断、学习进度记录和资源访问控制等模块。项目使用 Go、GoFrame、MySQL、Redis、Docker 和 Nginx 实现，围绕课程详情、学习进度、资源下载和后台配置等接口完成开发与联调。项目中设计了统一的课程学习权限判断逻辑，覆盖课程状态、学员权限、过期时间和强制允许/禁止等场景；学习进度模块通过接口上报并更新视频和文档学习记录，避免重复上报导致进度回退；资源下载接口补充课程归属和学习权限校验，降低越权访问风险。通过该项目，我对真实业务中的权限边界、接口安全、数据一致性和部署验收流程有了较完整的实践。"},{"name":"校园招聘信息聚合与岗位收藏系统","role":"后端主要开发者","start_date":"2024-04","end_date":"2024-07","description":"面向学生求职场景，开发校园招聘信息聚合与岗位收藏系统，支持岗位列表、岗位详情、关键词搜索、城市筛选、岗位收藏和投递状态记录等功能。我主要负责岗位、收藏、用户投递记录相关接口开发，并参与数据库表结构设计。项目使用 Java、Spring Boot、MyBatis Plus、MySQL 和 Redis 实现，岗位数据通过后台维护后展示给前端，用户收藏和投递状态通过接口记录。开发中重点处理了岗位分页查询、筛选条件组合、收藏幂等、重复投递校验和接口返回结构统一等问题。通过该项目，我进一步熟悉了后台业务系统中列表查询、状态记录、接口边界和前后端联调的开发流程。"},{"name":"在线考试与题库管理系统","role":"后端开发者","start_date":"2023-11","end_date":"2024-02","description":"独立完成在线考试与题库管理系统后端部分，支持题库维护、试卷生成、考试记录、成绩统计和后台管理等功能。项目使用 Spring Boot、MySQL、Redis 和 JWT 实现，围绕题目、试卷、考试记录和用户信息设计数据库表结构，并完成基础接口开发。项目中实现了按题型和难度组卷、考试记录保存、成绩计算和后台分页查询等功能；使用 Redis 缓存部分题型配置和考试状态信息，减少重复查询；通过统一异常处理和参数校验提升接口稳定性。该项目帮助我系统练习了数据库建模、业务状态设计、接口文档整理和基础缓存使用。"}]', '{"professional_skills":"Go、Java、Spring Boot、GoFrame、MyBatis Plus、MySQL、Redis、Docker、Nginx、Linux、Git、Maven、RESTful API、JWT、RBAC 基础、数据库事务、索引基础、缓存基础、幂等设计、接口鉴权、前后端联调、Postman、基础 SQL 优化、日志排查","ai_application":"熟悉使用 CodeBuddy、ChatGPT 等 AI 工具辅助需求拆解、接口设计、代码生成、Bug 定位、接口文档、测试用例和项目复盘。使用 AI 生成方案后会结合业务上下文、数据库字段、接口契约和运行结果进行二次校验，重点检查权限边界、异常处理、SQL 条件和前后端字段一致性。"}', '[{"company":"杭州某人工智能科技有限公司","position":"Go 后端开发实习生","start_date":"2025-02","end_date":"2025-05","description":"参与公司内部课程学习平台后端建设，负责课程权限、学习进度、资源访问和部分后台管理接口开发。实习期间使用 Go、GoFrame、MySQL、Redis、Docker 和 Nginx 完成接口开发、联调和部署验证。工作中围绕课程学习权限设计统一判断逻辑，覆盖登录态、课程状态、学员权限、过期时间和强制控制等场景；在学习进度模块中处理视频和文档进度上报，避免重复提交导致进度回退；在资源下载链路中补充课程归属和学习权限校验，修复仅校验登录态带来的越权风险；参与 Docker Compose、Nginx 静态资源和后端服务部署验证。通过这段实习，我对企业项目中的接口安全、权限校验、数据链路、前后端联调和上线前验收有了更系统的理解。"}]', '{"language_exams":[{"type":"CET-4","score":"528"}],"certificates":[{"name":"阿里云云计算高级工程师 ACP","description":"云计算方向认证，覆盖云服务器、网络、数据库、存储、安全和基础运维等内容，对云上部署和资源管理有较系统的理解。"},{"name":"软件设计师","description":"计算机技术与软件专业技术资格考试中级证书，覆盖软件工程、数据库、操作系统、计算机网络和程序设计基础。"}]}', '[{"name":"安徽省职业技能大赛 Web 赛项二等奖","description":"省级技能竞赛奖项，主要考察 Web 系统开发、数据库设计、接口实现和页面联调能力。"},{"name":"校级优秀学生干部","description":"在班级和学院工作中负责活动组织、通知协调和材料整理，具备较好的执行力和沟通能力。"}]', '{"works":[{"name":"企业课程学习平台","url":"https://demo.example.com/course-learning-platform","password":""},{"name":"校园招聘信息聚合与岗位收藏系统","url":"https://github.com/demo-user/campus-job-system","password":""},{"name":"在线考试与题库管理系统","url":"https://github.com/demo-user/online-exam-system","password":""}],"homepage":"https://github.com/demo-user"}', '{"additional_info":"我以 Go / Java 后端开发实习为主要目标，已经具备较完整的业务系统开发、接口联调和基础部署经验。相比单纯课程项目，我更重视真实业务中的权限边界、数据一致性、接口安全和上线前验证。过去的项目和实习经历让我逐渐形成了从需求拆解、接口设计、数据库建模、代码实现、联调测试到文档沉淀的开发习惯。目前简历已经接近投递状态，但仍希望进一步优化项目表达，把核心职责、技术难点和结果产出描述得更清楚。后续希望在真实后端团队中继续提升系统设计、缓存一致性、SQL 优化、并发处理和线上问题排查能力。"}' ),

-- ===== 09-211后台开发-基础薄弱版-简历优化 =====
(209, 2, 2, '09-211后台开发-基础薄弱版-简历优化', '{"name":"赵承宇","phone":"13900010009","email":"zhaochengyu.basic@example.com","city":"杭州"}', '[{"school":"杭州电子科技大学","degree":"本科","major":"软件工程","department":"计算机学院","start_date":"2022-09","end_date":"2026-06","gpa":"3.21","gpa_scale":"4.0","rank":"前 45%","core_courses":"数据结构、操作系统、计算机网络、数据库系统、Java 程序设计、软件工程、Web 应用开发、Linux 基础","research_direction":"","lab":"","paper_summary":""}]', '[{"name":"学生信息管理系统","role":"后端开发成员","start_date":"2023-10","end_date":"2023-12","description":"课程设计项目，主要实现学生信息、班级信息和成绩信息的基础管理功能。我参与了部分后端接口开发和数据库表设计，使用 Java、Spring Boot 和 MySQL 完成学生列表查询、新增、修改、删除等功能。项目整体以基础增删改查为主，接口逻辑较简单，主要帮助我熟悉了 Spring Boot 项目结构、Controller 和 Service 分层、MySQL 表设计以及 Postman 接口测试流程。目前对事务、权限校验、缓存和异常处理等内容理解还不够深入。"},{"name":"简易在线笔记系统","role":"个人开发者","start_date":"2024-03","end_date":"2024-05","description":"为了练习 Web 后端开发，独立完成了一个简易在线笔记系统，支持用户登录、笔记创建、笔记列表、笔记修改和删除等功能。后端使用 Spring Boot 和 MySQL 实现，前端使用简单 Vue 页面完成交互。项目中实现了基础登录校验和笔记数据保存，但整体功能较基础，没有完整的权限模型、接口限流、缓存设计和部署流程。通过该项目，我对前后端分离开发、接口联调和数据库基础操作有了初步认识，但项目亮点和技术深度仍然不足。"},{"name":"校园失物招领平台原型","role":"后端协作者","start_date":"2024-09","end_date":"2024-11","description":"小组课程项目，围绕校园失物招领场景设计并实现基础信息发布和查询功能。我主要协助完成失物信息发布、列表查询和详情展示相关接口，使用 Spring Boot、MyBatis Plus 和 MySQL 完成简单业务开发。项目中涉及用户发布信息、按物品类型筛选和状态更新等功能，但多数实现仍停留在基础业务接口层面，对复杂查询优化、数据一致性和接口安全考虑较少。该项目暴露出我在需求拆解、接口边界设计和代码规范方面还需要进一步提升。"}]', '{"professional_skills":"Java、Spring Boot 基础、MyBatis Plus 基础、MySQL 基础、Redis 入门、Linux 基础、Git、Maven、Postman、RESTful API 基础、HTML、CSS、Vue 基础、基础 SQL 编写、接口联调","ai_application":"会使用 ChatGPT、CodeBuddy 等 AI 工具辅助理解报错、生成学习笔记、整理接口说明和排查简单 Bug。当前主要把 AI 作为学习辅助工具，能够根据生成结果进行简单修改，但对复杂业务逻辑、数据库设计和系统边界仍需要人工进一步学习和验证。"}', '[]', '{"language_exams":[{"type":"CET-4","score":"462"}],"certificates":[{"name":"全国计算机等级考试二级 Java","description":"掌握 Java 基础语法、面向对象编程和简单程序设计能力。"}]}', '[{"name":"软件工程课程设计合格项目","description":"课程设计项目完成基础功能实现，主要参与后端接口开发和数据库表设计。"}]', '{"works":[{"name":"学生信息管理系统","url":"https://github.com/demo-user/student-management-basic","password":""},{"name":"简易在线笔记系统","url":"https://github.com/demo-user/simple-note-system","password":""},{"name":"校园失物招领平台原型","url":"https://github.com/demo-user/lost-found-basic","password":""}],"homepage":"https://github.com/demo-user"}', '{"additional_info":"我目前希望往 Java 后端开发方向发展，已经学习过 Java、Spring Boot、MySQL 和基础 Web 开发，也完成过几个课程项目和个人练习项目。但整体来看，我的项目大多停留在基础增删改查和简单接口联调阶段，对 Redis、事务、索引优化、权限设计、接口安全、部署和线上问题排查的理解还比较浅。当前简历距离直接投递较成熟的后台开发实习岗位仍有差距，希望通过简历优化明确短板，并继续补充一个更完整的业务项目，把数据库设计、权限校验、缓存使用、异常处理、接口文档和部署流程系统练习一遍。"}' );

SET FOREIGN_KEY_CHECKS = 1;
